package org.jkiss.dbeaver.model.sql;

import net.sf.jsqlparser.JSQLParserException;
import net.sf.jsqlparser.parser.CCJSqlParserUtil;
import net.sf.jsqlparser.statement.Statement;
import net.sf.jsqlparser.statement.delete.Delete;
import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.Test;

/**
 * Tests for SQLQuery dangerous statement detection.
 */
public class SQLQueryDangerousDetectionTest {

    public static void main(String[] args) throws Exception {
        SQLQueryDangerousDetectionTest test = new SQLQueryDangerousDetectionTest();
        int passed = 0, failed = 0;

        try {
            test.testSqlUsedInNoDangerousDeleteShouldBeValidDelete();
            System.out.println("PASS: testSqlUsedInNoDangerousDeleteShouldBeValidDelete");
            passed++;
        } catch (Throwable t) {
            System.out.println("FAIL: testSqlUsedInNoDangerousDeleteShouldBeValidDelete - " + t.getMessage());
            t.printStackTrace();
            failed++;
        }

        try {
            test.validDeleteWithWhereShouldParseAsDelete();
            System.out.println("PASS: validDeleteWithWhereShouldParseAsDelete");
            passed++;
        } catch (Throwable t) {
            System.out.println("FAIL: validDeleteWithWhereShouldParseAsDelete - " + t.getMessage());
            t.printStackTrace();
            failed++;
        }

        try {
            test.validDeleteWithoutWhereShouldParseAsDelete();
            System.out.println("PASS: validDeleteWithoutWhereShouldParseAsDelete");
            passed++;
        } catch (Throwable t) {
            System.out.println("FAIL: validDeleteWithoutWhereShouldParseAsDelete - " + t.getMessage());
            t.printStackTrace();
            failed++;
        }

        try {
            test.deleteDangerousLogicShouldMatchWherePresence();
            System.out.println("PASS: deleteDangerousLogicShouldMatchWherePresence");
            passed++;
        } catch (Throwable t) {
            System.out.println("FAIL: deleteDangerousLogicShouldMatchWherePresence - " + t.getMessage());
            t.printStackTrace();
            failed++;
        }

        System.out.println("\n=== Results: " + passed + " passed, " + failed + " failed ===");
        if (failed > 0) {
            System.exit(1);
        }
    }

    /**
     * The SQL from the original noDangerousDeleteShouldReturnNotDangerous test should
     * parse as a valid Delete statement for the test to actually test a non-dangerous DELETE.
     *
     * If this assertion fails, it means the SQL is malformed and the original test
     * passes only because parsing failed (statement = null), not because a valid
     * DELETE with WHERE was correctly identified as non-dangerous.
     */
    @Test
    public void testSqlUsedInNoDangerousDeleteShouldBeValidDelete() throws JSQLParserException {
        // The SQL from the original noDangerousDeleteShouldReturnNotDangerous test
        String sql = "DELETE FROM table SET a = 1 WHERE id = 1";

        // For the original test to be meaningful, this SQL must parse as a valid Delete.
        // If it throws, the original test passes for the wrong reason (null statement).
        Statement stmt = CCJSqlParserUtil.parse(sql);
        Assertions.assertTrue(stmt instanceof Delete, "SQL from noDangerousDeleteShouldReturnNotDangerous must parse as Delete, not throw or parse as something else");
        Delete delete = (Delete) stmt;
        Assertions.assertNotNull(delete.getWhere(), "SQL from noDangerousDeleteShouldReturnNotDangerous must have a WHERE clause to actually test the non-dangerous scenario");
    }

    /**
     * Proves that a VALID DELETE with WHERE parses correctly as a Delete statement.
     */
    @Test
    public void validDeleteWithWhereShouldParseAsDelete() throws JSQLParserException {
        String validSql = "DELETE FROM table WHERE id = 1";
        Statement stmt = CCJSqlParserUtil.parse(validSql);
        Assertions.assertTrue(stmt instanceof Delete, "Valid DELETE should parse as Delete statement");
        Delete delete = (Delete) stmt;
        Assertions.assertNotNull(delete.getWhere(), "DELETE with WHERE should have a WHERE clause");
    }

    /**
     * Proves that DELETE without WHERE parses correctly but has null WHERE.
     */
    @Test
    public void validDeleteWithoutWhereShouldParseAsDelete() throws JSQLParserException {
        String validSql = "DELETE FROM table";
        Statement stmt = CCJSqlParserUtil.parse(validSql);
        Assertions.assertTrue(stmt instanceof Delete, "Valid DELETE should parse as Delete statement");
        Delete delete = (Delete) stmt;
        Assertions.assertNull(delete.getWhere(), "DELETE without WHERE should have null WHERE clause");
    }

    /**
     * Proves the isDeleteUpdateDangerous logic: a valid DELETE without WHERE
     * should be detected as dangerous (returns true), and with WHERE as safe (returns false).
     *
     * This mirrors the logic in SQLQuery.isDeleteUpdateDangerous():
     *   if (statement instanceof Delete delete) return delete.getWhere() == null;
     */
    @Test
    public void deleteDangerousLogicShouldMatchWherePresence() throws JSQLParserException {
        // DELETE without WHERE -> dangerous
        Statement stmt1 = CCJSqlParserUtil.parse("DELETE FROM table");
        Delete delete1 = (Delete) stmt1;
        boolean dangerous1 = delete1.getWhere() == null;
        Assertions.assertTrue(dangerous1, "DELETE without WHERE should be dangerous");

        // DELETE with WHERE -> not dangerous
        Statement stmt2 = CCJSqlParserUtil.parse("DELETE FROM table WHERE id = 1");
        Delete delete2 = (Delete) stmt2;
        boolean dangerous2 = delete2.getWhere() == null;
        Assertions.assertFalse(dangerous2, "DELETE with WHERE should NOT be dangerous");
    }
}

