package org.jkiss.dbeaver.model.sql;

import net.sf.jsqlparser.JSQLParserException;
import net.sf.jsqlparser.parser.CCJSqlParserUtil;
import net.sf.jsqlparser.statement.Statement;
import net.sf.jsqlparser.statement.delete.Delete;
import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.Test;

public class JSqlParserMalformedDeleteTest {
    public static void main(String[] args) throws Exception {
        int passed = 0, failed = 0;

        try {
            testMalformedDeleteWithSetClauseShouldNotParseAsDelete();
            System.out.println("PASS: malformedDeleteWithSetClauseShouldNotParseAsDelete");
            passed++;
        } catch (Throwable t) {
            System.out.println("FAIL: malformedDeleteWithSetClauseShouldNotParseAsDelete - " + t.getMessage());
            t.printStackTrace();
            failed++;
        }

        try {
            testValidDeleteWithWhereShouldParseAsDelete();
            System.out.println("PASS: validDeleteWithWhereShouldParseAsDelete");
            passed++;
        } catch (Throwable t) {
            System.out.println("FAIL: validDeleteWithWhereShouldParseAsDelete - " + t.getMessage());
            t.printStackTrace();
            failed++;
        }

        try {
            testValidDeleteWithoutWhereShouldParseAsDelete();
            System.out.println("PASS: validDeleteWithoutWhereShouldParseAsDelete");
            passed++;
        } catch (Throwable t) {
            System.out.println("FAIL: validDeleteWithoutWhereShouldParseAsDelete - " + t.getMessage());
            t.printStackTrace();
            failed++;
        }

        try {
            testDeleteDangerousLogicShouldMatchWherePresence();
            System.out.println("PASS: deleteDangerousLogicShouldMatchWherePresence");
            passed++;
        } catch (Throwable t) {
            System.out.println("FAIL: deleteDangerousLogicShouldMatchWherePresence - " + t.getMessage());
            t.printStackTrace();
            failed++;
        }

        System.out.println("\n=== Results: " + passed + " passed, " + failed + " failed ===");
        if (failed > 0) {
            System.exit(1);
        }
    }

    // Static methods mirroring the test methods
    private static void testMalformedDeleteWithSetClauseShouldNotParseAsDelete() {
        String malformedSql = "DELETE FROM table SET a = 1 WHERE id = 1";
        try {
            CCJSqlParserUtil.parse(malformedSql);
            throw new AssertionError("Malformed DELETE SQL with SET clause should fail to parse");
        } catch (JSQLParserException e) {
            // Expected — good
        }
    }

    private static void testValidDeleteWithWhereShouldParseAsDelete() throws JSQLParserException {
        String validSql = "DELETE FROM table WHERE id = 1";
        Statement stmt = CCJSqlParserUtil.parse(validSql);
        if (!(stmt instanceof Delete)) {
            throw new AssertionError("Valid DELETE should parse as Delete statement");
        }
        Delete delete = (Delete) stmt;
        if (delete.getWhere() == null) {
            throw new AssertionError("DELETE with WHERE should have a WHERE clause");
        }
    }

    private static void testValidDeleteWithoutWhereShouldParseAsDelete() throws JSQLParserException {
        String validSql = "DELETE FROM table";
        Statement stmt = CCJSqlParserUtil.parse(validSql);
        if (!(stmt instanceof Delete)) {
            throw new AssertionError("Valid DELETE should parse as Delete statement");
        }
        Delete delete = (Delete) stmt;
        if (delete.getWhere() != null) {
            throw new AssertionError("DELETE without WHERE should have null WHERE clause");
        }
    }

    private static void testDeleteDangerousLogicShouldMatchWherePresence() throws JSQLParserException {
        // DELETE without WHERE -> dangerous
        Statement stmt1 = CCJSqlParserUtil.parse("DELETE FROM table");
        Delete delete1 = (Delete) stmt1;
        boolean dangerous1 = delete1.getWhere() == null;
        if (!dangerous1) {
            throw new AssertionError("DELETE without WHERE should be dangerous");
        }

        // DELETE with WHERE -> not dangerous
        Statement stmt2 = CCJSqlParserUtil.parse("DELETE FROM table WHERE id = 1");
        Delete delete2 = (Delete) stmt2;
        boolean dangerous2 = delete2.getWhere() == null;
        if (dangerous2) {
            throw new AssertionError("DELETE with WHERE should NOT be dangerous");
        }
    }
}

