package org.jkiss.dbeaver.model.sql.semantics;

import java.lang.reflect.Field;

/**
 * Test that nodesIteratorAt uses effective size() (subtracting tombstones) 
 * instead of raw size field when selecting switch branches.
 * 
 * Bug: switch (this.size) uses raw size field which includes tombstones,
 * but should use this.size() which subtracts tombstonesCount.
 * 
 * When tombstonesCount > 0 and effective size is 0, the switch should hit
 * case 0, but with the bug it hits a non-zero branch.
 */
public class OffsetKeyedTreeMapTombstoneBugTest {

    public static void main(String[] args) {
        int passed = 0;
        int failed = 0;

        try {
            testNodesIteratorAtAllTombstonesViaReflection();
            passed++;
            System.out.println("PASS: testNodesIteratorAtAllTombstonesViaReflection");
        } catch (Throwable e) {
            failed++;
            System.out.println("FAIL: testNodesIteratorAtAllTombstonesViaReflection - " + e.getMessage());
            e.printStackTrace();
        }

        try {
            testNodesIteratorAtPartialTombstonesViaReflection();
            passed++;
            System.out.println("PASS: testNodesIteratorAtPartialTombstonesViaReflection");
        } catch (Throwable e) {
            failed++;
            System.out.println("FAIL: testNodesIteratorAtPartialTombstonesViaReflection - " + e.getMessage());
            e.printStackTrace();
        }

        System.out.println("\nResults: " + passed + " passed, " + failed + " failed");

        if (failed > 0) {
            System.exit(1);
        }
    }

    /**
     * Test that nodesIteratorAt uses size() method (effective size) not raw size field.
     * 
     * Setup via reflection: insert entries, then set tombstonesCount so that
     * raw size field = 3 but effective size() = 0.
     * 
     * Expected: switch should hit case 0 (empty iterator).
     * Bug behavior: switch hits case 3, trying to navigate a "non-empty" tree.
     */
    @SuppressWarnings("unchecked")
    private static void testNodesIteratorAtAllTombstonesViaReflection() throws Exception {
        OffsetKeyedTreeMap<String> map = new OffsetKeyedTreeMap<>();

        // Insert 3 entries
        map.put(100, "a");
        map.put(200, "b");
        map.put(300, "c");

        assertEquals("Map should have 3 entries", 3, map.size());

        // Use reflection to set tombstonesCount = 3, making effective size() = 0
        // while raw size field remains 3
        Field tombstonesField = OffsetKeyedTreeMap.class.getDeclaredField("tombstonesCount");
        tombstonesField.setAccessible(true);
        tombstonesField.setInt(map, 3);

        // Now: raw size = 3, tombstonesCount = 3, effective size() = 0
        assertEquals("Effective size() should be 0 with tombstonesCount=3", 0, map.size());

        // nodesIteratorAt should use size()=0 and hit case 0 branch
        // With the bug, it uses raw size=3 and hits case 3 branch
        OffsetKeyedTreeMap.NodesIterator<String> iter = map.nodesIteratorAt(150);

        // In an empty map:
        // - getCurrValue() should return null
        // - next() should return false (no elements to iterate)
        // - prev() should return false (no elements to iterate)
        assertNull("getCurrValue() should be null in effectively empty map", iter.getCurrValue());
        assertFalse("next() should return false in effectively empty map", iter.next());
        assertFalse("prev() should return false in effectively empty map", iter.prev());
    }

    /**
     * Test that nodesIteratorAt uses size() method (effective size) not raw size field.
     * 
     * Setup via reflection: insert 5 entries, set tombstonesCount = 3.
     * Effective size() = 2, raw size field = 5.
     * 
     * Expected: switch should hit case 2 (iterate 2 entries).
     * Bug behavior: switch hits case 5, potentially iterating wrong number of entries
     * or accessing null nodes that were conceptually removed.
     */
    @SuppressWarnings("unchecked")
    private static void testNodesIteratorAtPartialTombstonesViaReflection() throws Exception {
        OffsetKeyedTreeMap<String> map = new OffsetKeyedTreeMap<>();

        // Insert 5 entries
        map.put(100, "a");
        map.put(200, "b");
        map.put(300, "c");
        map.put(400, "d");
        map.put(500, "e");

        assertEquals("Map should have 5 entries", 5, map.size());

        // Use reflection to set tombstonesCount = 3
        Field tombstonesField = OffsetKeyedTreeMap.class.getDeclaredField("tombstonesCount");
        tombstonesField.setAccessible(true);
        tombstonesField.setInt(map, 3);

        // Now: raw size = 5, tombstonesCount = 3, effective size() = 2
        assertEquals("Effective size() should be 2 with tombstonesCount=3", 2, map.size());

        // The switch in nodesIteratorAt should use size()=2, not raw size=5
        // With size=2, the case 2 branch will handle the iteration correctly
        // With raw size=5, the case 5 (default) branch would be used

        // Count how many entries the iterator can traverse
        OffsetKeyedTreeMap.NodesIterator<String> iter = map.nodesIteratorAt(250);

        // Count all entries by iterating forward
        int forwardCount = 0;
        while (iter.next()) {
            forwardCount++;
        }

        // Count all entries by iterating backward
        iter = map.nodesIteratorAt(250);
        int backwardCount = 0;
        while (iter.prev()) {
            backwardCount++;
        }

        // With effective size 2, we should iterate exactly 2 entries
        assertEquals("Forward iteration should yield 2 entries (effective size)", 2, forwardCount);
        assertEquals("Backward iteration should yield 2 entries (effective size)", 2, backwardCount);
    }

    // Simple test utilities to avoid JUnit dependency
    private static void assertEquals(String msg, int expected, int actual) {
        if (expected != actual) {
            throw new AssertionError(msg + ": expected=" + expected + " actual=" + actual);
        }
    }

    private static void assertNull(String msg, Object actual) {
        if (actual != null) {
            throw new AssertionError(msg + ": expected null but was " + actual);
        }
    }

    private static void assertFalse(String msg, boolean condition) {
        if (condition) {
            throw new AssertionError(msg);
        }
    }
}

