package org.jkiss.dbeaver.model.sql;

import java.lang.reflect.Constructor;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.util.List;

/**
 * Tests that processFragment respects dmax when one input is empty.
 *
 * Bug: when aLen=0 (empty a array), submitRange is called with Operation.INSERT_B
 * and bLen as length, returning d=bLen. But the dmax check at line 209 is never
 * reached — the function returns bLen directly. When bLen > dmax, this causes
 * dmax to be exceeded silently without the check. Same for bLen=0 with aLen.
 */
public class DiffDmaxBypassTest {

    /**
     * When aLen=0 (empty a), the edit distance equals bLen.
     * With dmax=3 and bLen=10, the edit distance should be capped at 3.
     */
    public void diffEmptyARespectsDmax() throws Exception {
        Constructor<?> ctor = Diff.class.getDeclaredConstructor(
                Object[].class, Object[].class, Diff.EqualityComparator.class, int.class);
        ctor.setAccessible(true);

        String[] a = new String[0];
        String[] b = {"x1", "x2", "x3", "x4", "x5", "x6", "x7", "x8", "x9", "x10"};

        Diff.EqualityComparator<String> comp = new Diff.EqualityComparator<String>() {
            @Override
            public boolean equals(String x, String y) {
                return x.equals(y);
            }
        };
        @SuppressWarnings("unchecked")
        Diff<String> diff = (Diff<String>) ctor.newInstance(new Object[]{a, b, comp, 3});

        Method method = Diff.class.getDeclaredMethod("prepareDiffImpl",
                int.class, int.class, int.class, int.class);
        method.setAccessible(true);
        method.invoke(diff, 0, 0, 0, b.length);

        Field rangesField = Diff.class.getDeclaredField("ranges");
        rangesField.setAccessible(true);
        @SuppressWarnings("unchecked")
        List<Diff.Range> ranges = (List<Diff.Range>) rangesField.get(diff);

        int totalEditDistance = 0;
        for (Diff.Range r : ranges) {
            if (r.operation != Diff.Operation.MATCH_AB) {
                totalEditDistance += r.length;
            }
        }

        assert totalEditDistance <= 3 :
            "Total edit distance " + totalEditDistance + " exceeds dmax=3. " +
            "processFragment should check dmax when aLen=0.";
    }

    /**
     * When bLen=0 (empty b), the edit distance equals aLen.
     * With dmax=3 and aLen=10, the edit distance should be capped at 3.
     */
    public void diffEmptyBRespectsDmax() throws Exception {
        Constructor<?> ctor = Diff.class.getDeclaredConstructor(
                Object[].class, Object[].class, Diff.EqualityComparator.class, int.class);
        ctor.setAccessible(true);

        String[] a = {"x1", "x2", "x3", "x4", "x5", "x6", "x7", "x8", "x9", "x10"};
        String[] b = new String[0];

        Diff.EqualityComparator<String> comp2 = new Diff.EqualityComparator<String>() {
            @Override
            public boolean equals(String x, String y) {
                return x.equals(y);
            }
        };
        @SuppressWarnings("unchecked")
        Diff<String> diff = (Diff<String>) ctor.newInstance(new Object[]{a, b, comp2, 3});

        Method method = Diff.class.getDeclaredMethod("prepareDiffImpl",
                int.class, int.class, int.class, int.class);
        method.setAccessible(true);
        method.invoke(diff, 0, a.length, 0, 0);

        Field rangesField = Diff.class.getDeclaredField("ranges");
        rangesField.setAccessible(true);
        @SuppressWarnings("unchecked")
        List<Diff.Range> ranges = (List<Diff.Range>) rangesField.get(diff);

        int totalEditDistance = 0;
        for (Diff.Range r : ranges) {
            if (r.operation != Diff.Operation.MATCH_AB) {
                totalEditDistance += r.length;
            }
        }

        assert totalEditDistance <= 3 :
            "Total edit distance " + totalEditDistance + " exceeds dmax=3. " +
            "processFragment should check dmax when bLen=0.";
    }

    public static void main(String[] args) throws Exception {
        DiffDmaxBypassTest test = new DiffDmaxBypassTest();
        System.out.println("Running diffEmptyARespectsDmax...");
        try {
            test.diffEmptyARespectsDmax();
            System.out.println("  PASSED");
        } catch (AssertionError e) {
            System.out.println("  FAILED: " + e.getMessage());
            throw e;
        }
        System.out.println("Running diffEmptyBRespectsDmax...");
        try {
            test.diffEmptyBRespectsDmax();
            System.out.println("  PASSED");
        } catch (AssertionError e) {
            System.out.println("  FAILED: " + e.getMessage());
            throw e;
        }
        System.out.println("All tests passed!");
    }
}

